cd unpacked_q4 && python3 - <<'EOF'
import re
for f in ['ppt/theme/theme1.xml','ppt/theme/theme2.xml']:
    d=open(f).read()
    print('===',f,'len',len(d))
    cs=re.search(r'<a:clrScheme.*?</a:clrScheme>', d, re.S)
    if cs: print(re.sub(r'\s+',' ',cs.group(0))[:1500])
    fs=re.search(r'<a:fontScheme.*?</a:fontScheme>', d, re.S)
    if fs: print('FONTS:', re.sub(r'\s+',' ',fs.group(0))[:600])
    ef=re.search(r'<a:effectStyleLst>.*?</a:effectStyleLst>', d, re.S)
    if ef: print('EFFECTS:', re.sub(r'\s+',' ',ef.group(0))[:400])
EOF
